 const [batchNumber,setBatchNumber]=useState("");const [asOfDate,setAsOfDate]=useState(new Date().toISOString().slice(0,10));const [sourceDescription,setSourceDescription]=useState("");const [sourceDocumentReference,setSourceDocumentReference]=useState("");const [openingRows,setOpeningRows]=useState([{studentId:"",sourceReference:"",description:"",debitAmount:"",creditAmount:""}]);const [from,setFrom]=useState(new Date(new Date().getFullYear(),0,1).toISOString().slice(0,10));const [to,setTo]=useState(new Date().toISOString().slice(0,10));const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [message,setMessage]=useState("");const [refundEvidenceOperations,setRefundEvidenceOperations]=useState<any>(null);const [operationsAlerts,setOperationsAlerts]=useState<any>(null);const [operationsAlertStatus,setOperationsAlertStatus]=useState("ALL");const [refundEvidenceStatus,setRefundEvidenceStatus]=useState("ALL");const [refundReconNotes,setRefundReconNotes]=useState<Record<string,any[]>>({});const [refundReconEvidence,setRefundReconEvidence]=useState<Record<string,any[]>>({});const [refundReconOpen,setRefundReconOpen]=useState<Record<string,boolean>>({});

 const p520FinanceSummary=useMemo(()=>{const currencies=new Set<string>();const metrics:Record<string,any>={};const ensure=(currency:string)=>{const c=(currency||'INR').toUpperCase();currencies.add(c);return metrics[c]||(metrics[c]={billedCents:0,paidCents:0,concessionCents:0,outstandingCents:0,requestedCents:0,approvedPendingCents:0,settledCents:0,rejectedCents:0,chargeCount:0,invoiceCount:0});};for(const charge of feeChargeRows){if(['VOID','DRAFT'].includes(String(charge.status||'').toUpperCase()))continue;const m=ensure(charge.currency);m.chargeCount++;m.billedCents+=Math.max(0,Math.round(Number(charge.amount||0)*100));m.paidCents+=Math.max(0,Math.round(Number(charge.amountPaid||0)*100));m.concessionCents+=(charge.concessions||[]).filter((x:any)=>x.status==='APPROVED').reduce((sum:number,x:any)=>sum+Math.round(Number(x.calculatedAmount||0)*100),0);}for(const invoice of feeInvoiceRows){if(String(invoice.status||'').toUpperCase()!=='VOID')ensure(invoice.currency).invoiceCount++;}for(const refund of refundRows){const m=ensure(refund.currency);const cents=Math.max(0,Math.round(Number(refund.amount||0)*100));switch(String(refund.status||'').toUpperCase()){case 'REQUESTED':m.requestedCents+=cents;break;case 'APPROVED_PENDING_SETTLEMENT':m.approvedPendingCents+=cents;break;case 'SETTLED':m.settledCents+=cents;break;case 'REJECTED':m.rejectedCents+=cents;break;}}for(const currency of currencies){const m=metrics[currency];m.outstandingCents=Math.max(0,m.billedCents-m.concessionCents-m.paidCents);}const fmt=(currency:string,cents:number)=>`${currency} ${(cents/100).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}`;return {currencies:Array.from(currencies).sort(),metrics,fmt,charges:feeChargeRows.length,invoices:feeInvoiceRows.length,refunds:refundRows.length,overdue:(p517Balances?.rows||[]).filter((r:any)=>Number(r.daysPastDue)>0&&Number(r.outstanding)>0).length,latePreview:(p517Balances?.rows||[]).reduce((n:number,r:any)=>n+Math.round(Number(r.lateFeePreview||0)*100),0),lateCurrency:p517Policy.currency||'INR',lateEnabled:!!p517Policy.enabled,paymentMethods:configuredPaymentMethods.length};},[feeChargeRows,feeInvoiceRows,refundRows,p517Balances,p517Policy,configuredPaymentMethods]);
