 useEffect(()=>{if(!configured)return;let active=true;const url=`${api.replace(/\/+$/,'')}/api/v1/finance/${encodeURIComponent(org)}/${encodeURIComponent(school)}/configuration`;request(url).then(async response=>{if(!response.ok)return;const payload=await response.json();const methods=payload?.data?.configuration?.paymentMethods;if(Array.isArray(methods)&&active){const enabled=methods.filter((m:any)=>m?.enabled&&typeof m.code==='string').map((m:any)=>({code:m.code.toUpperCase(),label:String(m.label||m.code)}));setConfiguredPaymentMethods(enabled.length?enabled:[]);}}).catch(()=>{});return()=>{active=false;};},[configured,api,org,school,request]);

