  {can('accounting.reconcile')&&<div className="subsection"><h3>Operational alert history</h3><p className="helper">Tenant-scoped alert delivery history. Platform-wide worker events without tenant attribution are intentionally excluded. Acknowledgements are audited; delivered and acknowledged records are retained for 90 days by policy.</p><div className="button-row"><label>Alert status <select value={operationsAlertStatus} onChange={e=>{setOperationsAlertStatus(e.target.value);void loadOperationsAlerts(e.target.value);}}><option value="ALL">All statuses</option><option value="PENDING">Pending</option><option value="RETRY">Retry required</option><option value="SENDING">Sending</option><option value="DELIVERED">Delivered</option></select></label><button type="button" disabled={busy} onClick={()=>void loadOperationsAlerts()}>Refresh alerts</button></div><div className="grade-list">{(operationsAlerts?.rows||[]).map((alert:any)=><div className="grade-row" key={alert.id}><b>{alert.severity} · {alert.eventType} · {alert.status}</b><small>Created {String(alert.createdAt).slice(0,19)} · Attempts {alert.attempts} · Delivered {alert.deliveredAt?String(alert.deliveredAt).slice(0,19):'—'}</small>{alert.lastErrorCode&&<small>Last delivery error: {alert.lastErrorCode} · Next retry {String(alert.nextAttemptAt).slice(0,19)}</small>}{alert.acknowledgedAt?<small>Acknowledged {String(alert.acknowledgedAt).slice(0,19)} by {alert.acknowledgedByUserId}</small>:<button type="button" disabled={busy} onClick={()=>void acknowledgeOperationsAlert(alert.id)}>Acknowledge</button>}{alert.status==='RETRY'&&<button type="button" disabled={busy} onClick={()=>void retryOperationsAlert(alert.id)}>Retry delivery</button>}</div>)}{!(operationsAlerts?.rows||[]).length&&<p className="helper">No tenant-scoped operational alerts are available.</p>}</div></div>}
